"use client";
/**
 * Tiny Line Chart: an SVG sparkline for stat tiles, table rows and inline
 * labels. The curve eases between points, the ends can fade out, and an
 * optional gradient fills the area below. The colour reads a CSS variable,
 * so a theme can restyle every chart at once.
 */
import { useEffect, useId, useMemo, useRef, type CSSProperties } from "react";

export type TinyChartEasing = "linear" | "low" | "ease";
export type TinyChartSize = "s" | "m" | "l";

const SIZES: Record<TinyChartSize, { width: number; height: number; stroke: number }> = {
  s: { width: 56, height: 18, stroke: 1.5 },
  m: { width: 192, height: 60, stroke: 2 },
  l: { width: 300, height: 90, stroke: 2.5 },
};
/** How far each control point reaches toward its neighbours. */
const REACH: Record<TinyChartEasing, number> = { linear: 0, low: 0.18, ease: 0.3 };

/** A smooth path through the points, with control points kept inside each segment's range. */
export function sparklinePath(points: [number, number][], reach: number): string {
  if (!points.length) return "";
  const [x0, y0] = points[0];
  let d = `M${x0.toFixed(2)},${y0.toFixed(2)}`;
  for (let i = 1; i < points.length; i++) {
    const [x1, y1] = points[i - 1];
    const [x2, y2] = points[i];
    if (!reach) {
      d += `L${x2.toFixed(2)},${y2.toFixed(2)}`;
      continue;
    }
    const [px, py] = points[i - 2] ?? points[i - 1];
    const [nx, ny] = points[i + 1] ?? points[i];
    const lo = Math.min(y1, y2);
    const hi = Math.max(y1, y2);
    const clamp = (v: number) => Math.min(hi, Math.max(lo, v));
    const c1x = x1 + (x2 - px) * reach;
    const c1y = clamp(y1 + (y2 - py) * reach);
    const c2x = x2 - (nx - x1) * reach;
    const c2y = clamp(y2 - (ny - y1) * reach);
    d += `C${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${x2.toFixed(2)},${y2.toFixed(2)}`;
  }
  return d;
}

export interface TinyLineChartProps {
  data: number[];
  size?: TinyChartSize;
  /** Overrides the size preset. */
  width?: number;
  height?: number;
  strokeWidth?: number;
  /** Any CSS colour; by default `--tiny-chart-color`, then blue. */
  color?: string;
  easing?: TinyChartEasing;
  /** A gradient under the line. */
  fill?: boolean;
  /** Fade the line out at both ends. */
  fade?: boolean;
  /** Draw the line in when it first appears. */
  animate?: boolean;
  "aria-label"?: string;
  className?: string;
  style?: CSSProperties;
}

export function TinyLineChart({
  data,
  size = "m",
  width,
  height,
  strokeWidth,
  color = "var(--tiny-chart-color, #3b5bdb)",
  easing = "low",
  fill = false,
  fade = true,
  animate = true,
  "aria-label": label,
  className,
  style,
}: TinyLineChartProps) {
  const preset = SIZES[size];
  const w = width ?? preset.width;
  const h = height ?? preset.height;
  const stroke = strokeWidth ?? preset.stroke;
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const lineRef = useRef<SVGPathElement>(null);

  const { line, area } = useMemo(() => {
    const values = data.filter((v) => Number.isFinite(v));
    if (values.length < 2) return { line: "", area: "" };
    const min = Math.min(...values);
    const max = Math.max(...values);
    const pad = stroke / 2 + 1;
    const span = max - min || 1;
    const points = values.map((v, i): [number, number] => [
      pad + (i / (values.length - 1)) * (w - 2 * pad),
      pad + (1 - (v - min) / span) * (h - 2 * pad),
    ]);
    const path = sparklinePath(points, REACH[easing]);
    return { line: path, area: `${path}L${points[points.length - 1][0].toFixed(2)},${h}L${points[0][0].toFixed(2)},${h}Z` };
  }, [data, w, h, stroke, easing]);

  useEffect(() => {
    const path = lineRef.current;
    if (!animate || !path || !path.animate || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
    const run = path.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: 700, easing: "cubic-bezier(0.25, 0.8, 0.25, 1)" });
    return () => run.cancel();
  }, [line, animate]);

  const mask = fade ? `url(#${id}-fade)` : undefined;
  return (
    <svg
      width={w}
      height={h}
      viewBox={`0 0 ${w} ${h}`}
      role="img"
      aria-label={label ?? `Trend of ${data.length} values`}
      className={className}
      style={{ display: "block", overflow: "visible", color, flex: "none", ...style }}
    >
      <defs>
        {fade ? (
          <>
            <linearGradient id={`${id}-edge`} x1="0" x2="1" y1="0" y2="0">
              <stop offset="0" stopColor="#fff" stopOpacity="0" />
              <stop offset="0.14" stopColor="#fff" stopOpacity="1" />
              <stop offset="0.86" stopColor="#fff" stopOpacity="1" />
              <stop offset="1" stopColor="#fff" stopOpacity="0" />
            </linearGradient>
            <mask id={`${id}-fade`} maskUnits="userSpaceOnUse" x={-stroke} y={-stroke} width={w + 2 * stroke} height={h + 2 * stroke}>
              <rect x={-stroke} y={-stroke} width={w + 2 * stroke} height={h + 2 * stroke} fill={`url(#${id}-edge)`} />
            </mask>
          </>
        ) : null}
        {fill ? (
          <linearGradient id={`${id}-area`} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0" stopColor="currentColor" stopOpacity="0.22" />
            <stop offset="1" stopColor="currentColor" stopOpacity="0" />
          </linearGradient>
        ) : null}
      </defs>
      <g mask={mask}>
        {fill && area ? <path d={area} fill={`url(#${id}-area)`} /> : null}
        {line ? (
          <path
            ref={lineRef}
            d={line}
            fill="none"
            stroke="currentColor"
            strokeWidth={stroke}
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={animate ? 1 : undefined}
            vectorEffect="non-scaling-stroke"
          />
        ) : null}
      </g>
    </svg>
  );
}
